import{_ as t,o,c as a,ag as d}from"./chunks/framework.HG0H2VLS.js";const p=JSON.parse('{"title":"TableListing — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/patterns/TableListing/TableListing.figma-notes.md","filePath":"public/demos/src/patterns/TableListing/TableListing.figma-notes.md"}'),i={name:"public/demos/src/patterns/TableListing/TableListing.figma-notes.md"};function n(s,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="tablelisting-—-figma-notes" tabindex="-1">TableListing — Figma Notes <a class="header-anchor" href="#tablelisting-—-figma-notes" aria-label="Permalink to &quot;TableListing — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 5) <strong>Files:</strong> <code>TableListing.css</code>, <code>TableListing.html</code>, <code>TableListing.figma.ts</code>, <code>TableListing.figma-notes.md</code><strong>Composes:</strong> TableCard (one per table), Toggle (<code>toggle--xxs</code>), Input (<code>input--sm</code>, label-less) <strong>JS:</strong> none</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3488:196339</code></li></ul><h2 id="variant-matrix-2-variants" tabindex="-1">Variant matrix (2 variants) <a class="header-anchor" href="#variant-matrix-2-variants" aria-label="Permalink to &quot;Variant matrix (2 variants)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Device</th><th>Node</th><th>Figma size</th><th>CSS</th></tr></thead><tbody><tr><td>Pattern</td><td>Desktop</td><td><code>3474:91854</code></td><td>1180×729</td><td><code>.table-listing</code></td></tr><tr><td>Pattern</td><td>Mobile</td><td><code>3488:196340</code></td><td>390×2019</td><td><code>@media (max-width: 767px)</code></td></tr></tbody></table><p>Tier is single-valued (<code>Pattern</code>). There is no Type or State axis — this pattern is a container, and all its state lives in the TableCards it holds.</p><h2 id="the-grid-auto-fill-not-four-fixed-columns" tabindex="-1">The grid: auto-fill, not four fixed columns <a class="header-anchor" href="#the-grid-auto-fill-not-four-fixed-columns" aria-label="Permalink to &quot;The grid: auto-fill, not four fixed columns&quot;">​</a></h2><p>Figma specifies <code>repeat(4, minmax(0,1fr))</code> on desktop and <code>repeat(1, …)</code> on mobile, with 8px gaps. Built as:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">grid-template-columns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: repeat(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-fill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, minmax(var(--ai-size-4), 1fr));</span></span></code></pre></div><p><strong>Why, and why it is not a divergence in practice.</strong> TableCard carries a 240px <code>min-inline-size</code>, so four fixed columns need roughly 984px; between 768px and ~1000px Figma&#39;s literal rule would overflow its own container. auto-fill avoids that without inventing a breakpoint, and it reproduces Figma exactly at both drawn widths. Measured:</p><table tabindex="0"><thead><tr><th>Grid width</th><th>Columns</th><th>Column width</th></tr></thead><tbody><tr><td><strong>1148px</strong> (Figma&#39;s desktop)</td><td><strong>4</strong></td><td><strong>281px</strong> — exactly the cards Figma draws</td></tr><tr><td>1149px</td><td>4</td><td>281.25px</td></tr><tr><td>900px</td><td>3</td><td>294.7px</td></tr><tr><td><strong>358px</strong> (Figma&#39;s mobile)</td><td><strong>1</strong></td><td>full width</td></tr></tbody></table><p>So the two widths Figma specifies render identically to Figma, and the range in between steps down through 3 and 2 columns instead of breaking. The mobile single column falls out of the same rule, so <strong>the media query needs no grid rule at all</strong>. Designer&#39;s call 2026-08-25.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th></tr></thead><tbody><tr><td>root <code>padding</code></td><td><code>--ai-spacing-5</code> all round</td><td><code>--ai-spacing-4</code> inline, <code>--ai-spacing-5</code> block</td></tr><tr><td>toolbar <code>flex-direction</code></td><td><code>row</code></td><td><strong><code>column</code></strong> — title+filter, then a full-width search</td></tr><tr><td>toolbar <code>padding-block-end</code></td><td><code>--ai-spacing-3</code> (8px)</td><td><code>--ai-spacing-0</code></td></tr><tr><td>title <code>font-size</code></td><td><code>--ai-font-fixed-md</code> (18px)</td><td><code>--ai-font-fixed-sm</code> (16px)</td></tr><tr><td><code>__divider</code></td><td>present</td><td><strong><code>display: none</code></strong></td></tr><tr><td><code>__search</code></td><td><code>--ai-size-6</code> (320px)</td><td><code>100%</code></td></tr><tr><td>grid columns</td><td>4</td><td>1 — from auto-fill, no rule needed</td></tr></tbody></table><p>The &quot;Only free seats&quot; label is <strong>12px at both</strong> breakpoints — worth stating because it would be easy to assume it steps down with the title.</p><h2 id="toolbar-layout" tabindex="-1">Toolbar layout <a class="header-anchor" href="#toolbar-layout" aria-label="Permalink to &quot;Toolbar layout&quot;">​</a></h2><p>Desktop is one row: title | filter | divider | search. Figma splits the first two as equal <code>flex-1</code> columns (396px each in a 1148px toolbar), with the divider <code>shrink-0</code> and the search a fixed 320px.</p><p>Nesting title + filter inside <code>__toolbar-main</code> (itself <code>flex: 1 0 0</code>) reproduces those widths exactly — 396 + 12 + 396 = 804, then + 12 + 0 + 12 + 320 = 1148 — <strong>and</strong> gives the mobile two-row layout for free, since only <code>__toolbar</code> needs to flip to a column. Verified: the parts sum to the toolbar width at every desktop size tested.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td>root <code>background-color</code></td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>root <code>border-color</code>, divider <code>background-color</code></td><td></td></tr><tr><td><code>--ai-radius-lg</code></td><td>root <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>--ai-spacing-5</code></td><td>root <code>padding</code> (desktop), mobile <code>padding-block</code>, divider <code>block-size</code> (16px)</td><td></td></tr><tr><td><code>--ai-spacing-4</code></td><td>toolbar <code>gap</code>, mobile root <code>padding-inline</code> (12px)</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>root <code>gap</code>, toolbar <code>padding-block-end</code>, filter <code>gap</code>, grid <code>gap</code> (8px)</td><td></td></tr><tr><td><code>--ai-spacing-0</code></td><td>mobile toolbar <code>padding-block-end</code></td><td></td></tr><tr><td><code>--ai-size-6</code></td><td>search <code>inline-size</code> (320px)</td><td></td></tr><tr><td><code>--ai-size-4</code></td><td>grid column <code>minmax</code> floor (240px)</td><td>TableCard&#39;s own min-width</td></tr><tr><td><code>--ai-font-title</code></td><td>title, filter label</td><td></td></tr><tr><td><code>--ai-font-fixed-md</code> / <code>-sm</code></td><td>title, desktop / mobile</td><td></td></tr><tr><td><code>--ai-font-fixed-xxs</code></td><td>filter label (12px)</td><td>unbound in Figma — see below</td></tr><tr><td><code>--ai-font-bold</code> / <code>-medium</code></td><td>title / filter label</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code></td><td>title / filter label</td><td></td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>root <code>w-[1180px]</code> desktop / <code>w-[390px]</code> mobile</td><td><strong>Fluid <code>inline-size: 100%</code></strong> (designer, 2026-08-25). Both unbound and matching no token — they are just the frames Figma drew. This is the main content area, not a fixed rail, so the same call already taken for AttendeeCard and TableCard applies; the grid does the responsive work.</td></tr><tr><td>filter label <code>text-[12px]</code>, unbound</td><td><strong><code>--ai-font-fixed-xxs</code></strong>, which is exactly 12px, so binding it is visually a no-op. Same treatment as TableCard&#39;s company size. <strong>Worth binding in Figma.</strong></td></tr><tr><td>divider <code>line</code> node stroke, invisible in design context</td><td><strong><code>--ai-border-secondary</code></strong>, resolved by <code>get_variable_defs</code> on the node itself (<code>3474:91537</code>). Not a gap — just hidden behind an SVG asset.</td></tr><tr><td><code>--ai-font-fixed-2xs</code> (13px) and <code>--ai-font-fixed-xs</code> (14px) in the set&#39;s variable list</td><td><strong>Not gaps.</strong> Neither is used by anything in this pattern&#39;s own design context — phantoms of the same kind seen on TableDetail and Unassigned, likely bound on hidden layers or inside TableCard.</td></tr></tbody></table><h2 id="two-child-components-had-to-change" tabindex="-1">Two child components had to change <a class="header-anchor" href="#two-child-components-had-to-change" aria-label="Permalink to &quot;Two child components had to change&quot;">​</a></h2><p>Both were <strong>Case A</strong> — the variant or behaviour already existed in Figma, or had been worked around repeatedly; the components were simply behind.</p><h3 id="toggle-gained-a-xxs-size" tabindex="-1">Toggle gained a <code>xxs</code> size <a class="header-anchor" href="#toggle-gained-a-xxs-size" aria-label="Permalink to &quot;Toggle gained a `xxs` size&quot;">​</a></h3><p>The toolbar toggle is <code>Toggle</code> at <code>size=&quot;xxs&quot;</code> — <strong>a real variant in Toggle&#39;s Figma set</strong> (<code>2025:1081</code> Initial, <code>3435:28284</code> Active), which our component did not have. Added <code>.toggle--xxs</code>: 24×12 track (<code>--ai-spacing-6</code> × <code>--ai-spacing-4</code>), 8×8 knob (<code>--ai-spacing-3</code>), all tokens. Verified 24×12 / 8×8, knob at 2.5px → 13.5px, track <code>--ai-border-secondary</code> → <code>--ai-surface-brand</code>.</p><p>Figma defines <strong>only Initial and Active</strong> for this size — no Disabled — so no Disabled row was added to Toggle&#39;s demo. The generic <code>--disabled</code> still composes if a consumer ever needs it.</p><p>One 0.5px difference: Figma puts the active knob at <code>left: 14px</code> (a 2px right inset against a 2.5px left inset). Toggle&#39;s own convention across every other size is a symmetric <code>calc(100% - knob - 2.5px)</code>, which yields 13.5px. Internal consistency was preferred over matching an asymmetry that reads as a Figma nudge.</p><h3 id="input-lost-its-192px-cap" tabindex="-1">Input lost its 192px cap <a class="header-anchor" href="#input-lost-its-192px-cap" aria-label="Permalink to &quot;Input lost its 192px cap&quot;">​</a></h3><p>The search is 320px, but <code>.input--sm .input__wrap</code> carried <code>max-width: var(--ai-size-3)</code> (192px), so an <code>input--sm</code> could never fill its container. <strong>Removed from Input entirely</strong> at the designer&#39;s direction, rather than overridden again — a <em>size</em> modifier should govern height, padding and typography, not cap width, and it had already been worked around in three places:</p><ul><li><code>Datatables.css</code> lifted it in a media query, with a comment naming the cap</li><li><code>ControlScreen.html</code> used an inline <code>style=&quot;max-width: none&quot;</code> (that one targets <code>.datatables__search</code>&#39;s own 18rem cap, so it stays)</li><li><code>Unassigned.css</code> needed a scoped override the day before</li></ul><p><strong>Proved safe before removing it:</strong> every <code>input--sm</code> wrap in Datatables and ControlScreen was measured at 1400px and 500px before and after — <strong>byte-identical</strong> (288/288/266/266 and 0/297). The cap was blocking new consumers without shaping any existing one. The two now-redundant workarounds (Datatables&#39; media-query rule, Unassigned&#39;s override) were removed and their comments corrected.</p><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><ul><li><strong>Presentational only, no JS.</strong> The free-seats toggle and the search both filter the grid, which is the parent module&#39;s job — this pattern renders what it is given.</li><li>The toggle is a real <code>&lt;button role=&quot;switch&quot; aria-checked&gt;</code> with the label wired via <code>aria-labelledby</code>, and the label is a <code>&lt;label for&gt;</code> so clicking the text also hits the control.</li><li>The search is <code>&lt;input type=&quot;search&quot;&gt;</code> with an <code>aria-label</code>, since there is no visible label.</li><li>TableCards bring their own selection contract — the parent toggles <code>--selected</code> on them.</li></ul><h2 id="the-toggle-works-the-filtering-is-deliberately-absent" tabindex="-1">The toggle works; the filtering is deliberately absent <a class="header-anchor" href="#the-toggle-works-the-filtering-is-deliberately-absent" aria-label="Permalink to &quot;The toggle works; the filtering is deliberately absent&quot;">​</a></h2><p>The &quot;Only free seats&quot; switch flips itself — <code>Toggle</code> gained <code>Toggle.js</code> on 2026-08-26, so the component owns its own <code>.toggle--active</code> and <code>aria-checked</code>. This page just includes the script.</p><p><strong>The filtering is a separate thing and is deliberately not here.</strong> Deriving &quot;only free seats&quot; belongs to the parent module and the backend (<code>seating-free-seats-filter</code>); a consumer that needs to react listens for <code>toggle:change</code> and reads <code>detail.active</code>.</p><p>Clicking the &quot;Only free seats&quot; text also flips it, via <code>label[for]</code> + <code>aria-labelledby</code>.</p><blockquote><p>This pattern briefly carried its own inline flip, which was the ninth copy of the same three lines across the repo. Removing all nine is what prompted <code>Toggle.js</code> — see <code>Toggle.figma-notes.md</code>.</p></blockquote><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>A hidden <code>View Actions</code> frame</strong> sits at the end of the toolbar (<code>3474:91539</code>, <code>hidden=&quot;true&quot;</code>) holding two 32×32 Buttons — presumably a grid/list view switch. <strong>Not built</strong>, because it is hidden. Worth confirming whether it is coming, since it would change the toolbar&#39;s right-hand group.</li><li><strong>Sponsor row and tier pill are <code>hidden=&quot;true&quot;</code></strong> on every TableCard instance here, so the cards render with just title, bar, legend and footer. That is TableCard&#39;s existing optional markup — no change needed to it.</li><li><strong><code>get_design_context</code> on either variant returns ~68KB</strong> and expands all thirteen TableCards. Fetch the toolbar frame (<code>3474:91531</code>) on its own, or extract the shell lines with a script.</li><li><strong>The published Code Connect for Input is stale here too</strong> — the snippet emits <code>class=&quot;input__field&quot;</code> where the class is <code>input__control</code>. Same finding as Unassigned; a re-publish fixes it.</li><li><strong>The registry cites node <code>2025:1080</code> for both Toggle and ToggleDS.</strong> That node is Toggle&#39;s set, so ToggleDS&#39;s row points at the wrong component. Worth correcting.</li><li><strong>No hover, focus, pressed or disabled variants</strong> for the pattern itself, and no dark-mode variant.</li><li><strong>Harness note.</strong> CSS transitions do not advance under Chrome&#39;s <code>--virtual-time-budget</code>, so a transitioned property (this toggle animates <code>left</code> and <code>background-color</code>) reads its <em>start</em> value forever after a class change — it looks broken when it is not. Inject <code>* { transition: none !important }</code> in the probe to measure the settled state.</li></ul><hr><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Self-container.</strong> <code>.table-listing</code> sets <code>container-type: inline-size; container-name: table-listing</code>; its descendant rules key on it. The root&#39;s own padding <strong>cannot</strong> — an element never matches a query on the container it declares — so that one rule keys on <code>cs-page</code>.</p><p><strong>The search field was the real bug.</strong> It had <code>flex-shrink: 0</code> and a hard <code>inline-size: var(--ai-size-6)</code>, so it held its full 320px inside a 382px toolbar, leaving 62px for the title and filter together: the title got a 13px box. Now <code>flex: 0 1 var(--ai-size-6)</code> with <code>max-inline-size: var(--ai-size-6)</code> and <code>min-inline-size: 0</code> — 320 is a <strong>cap</strong>, not a floor. The stacked block releases the cap (<code>max-inline-size: none</code>) so the field still fills the row, which is what Figma&#39;s mobile frame draws.</p><p>Note the side effect, which is correct: the listing reacts to <strong>its own</strong> width, so when the detail panel takes 320 the listing can be narrow enough to stack its toolbar while the header above — which spans the full page — does not.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p><h2 id="cards-stretch-to-equal-height-on-a-row-designer-2026-09-10" tabindex="-1">Cards stretch to equal height on a row (designer, 2026-09-10) <a class="header-anchor" href="#cards-stretch-to-equal-height-on-a-row-designer-2026-09-10" aria-label="Permalink to &quot;Cards stretch to equal height on a row (designer, 2026-09-10)&quot;">​</a></h2><p>Reported: <em>&quot;the cards should stretch so they are the same height on the row. also their alignment should be start, it should not be evenly spaced.&quot;</em></p><p>Source: <code>lRKvtYSU3SvO5hbMT33jxw</code> <code>1:31485</code> — the Table Listing instance in the <strong>Seating Planner</strong> file, not the Design System file this pattern was originally built from.</p><p>Figma&#39;s grid frame (<code>I1:31485;1:58398;1:31252</code>) reads:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grid  grid-cols-[repeat(4,minmax(0,1fr))]  gap-x-[8px] gap-y-[8px]</span></span>\n<span class="line"><span>grid-rows-[186px 164px 150px]</span></span></code></pre></div><p>It declares <strong>no <code>align-items</code></strong>, so it takes the CSS default <code>stretch</code> — and the measured geometry confirms it: every card in a row is exactly its row track, 186 / 164 / 150, even though their content heights differ (row 1 has a two-line legend and a sponsor row on cards 1–2, and neither on cards 3–4).</p><p>The grid rule had <code>align-items: start</code>, which measured <strong>[190, 190, 155, 155]</strong> on row 1. Changed to <code>stretch</code>.</p><h3 id="and-align-content-start-which-the-first-pass-missed" tabindex="-1">…and <code>align-content: start</code>, which the first pass missed <a class="header-anchor" href="#and-align-content-start-which-the-first-pass-missed" aria-label="Permalink to &quot;…and `align-content: start`, which the first pass missed&quot;">​</a></h3><p><code>align-items: stretch</code> alone was not enough, and got it wrong in the other direction — reported as <em>&quot;the cards don&#39;t stretch to fill the container, there is a space at the bottom. they just need to stretch to match heights on the same row.&quot;</em></p><p>Two axes of the same word, and only one of them was wanted:</p><table tabindex="0"><thead><tr><th>Property</th><th>Governs</th><th>Wanted</th></tr></thead><tbody><tr><td><code>align-items</code></td><td>how a card sits in <strong>its row</strong></td><td><code>stretch</code> — match the row</td></tr><tr><td><code>align-content</code></td><td>how the <strong>rows</strong> sit in the grid box</td><td><code>start</code> — do <em>not</em> fill the box</td></tr></tbody></table><p>A grid&#39;s default <code>align-content: normal</code> behaves as <code>stretch</code>. In the Seating Planner this grid is a flex item filling the panel height, so once the cards stretched to their tracks, the auto tracks themselves grew to swallow the whole box: <strong>the Press Room&#39;s three cards measured 397px each — the full grid height — with zero space beneath them.</strong> Figma leaves that space empty: <code>1:31485</code> is a 698px listing holding 580px of content.</p><p><strong>Why the first verification passed anyway:</strong> it only reproduces when the container is TALLER than the content. Main Ballroom&#39;s 13 cards overflow and scroll, and <code>align-content</code> does nothing at all in that case — so the plan I measured was the one plan that could not show the bug. Checking a short plan is the test that matters here.</p><p>Verified across all four plans after adding it: Main Ballroom [190×4] / [168×4] / [155×4] / [155] (scrolling, 13 cards), Overflow Annex [177×4] / [155×2] with 57px left at the bottom, VIP Lounge [155×4] and Press Room [155×3] each with 242px left. Every row internally equal, no row filling the box.</p><p>Horizontally nothing changed and nothing needed to: <code>justify-content</code> computes to <code>normal</code> and the four columns fill the content box exactly (4 × 242.75 + 3 × 8 = 995, the 1010px border box less the 15px scrollbar gutter), and <code>auto-fill</code> with <code>minmax(--ai-size-4, 1fr)</code> stays as it was. There was never any even spacing to remove on that axis.</p><p><strong>Where the slack goes is TableCard&#39;s decision, and Figma pins the footer.</strong> The seated-count row sits a constant 16px — the card&#39;s own padding — from the bottom in all three tracks (footer at y=146 in the 186 row, 124 in 164, 110 in 150), while <code>Visualization-Slot</code> grows past its content: 41px holding 28px of bar+legend in row 1, 41 holding 27 in row 2, a natural 27 in row 3. So the bar/legend block absorbs it and the footer stays put — implemented as <code>flex: 1 1 auto</code> on <code>.table-card__viz</code>, documented in TableCard.css.</p><p><strong>Figma&#39;s own instances disagree on where the content sits inside the grown slot</strong> — <code>1:31319</code> centres its bar+legend at y=6.5, <code>1:31336</code> tops it at y=0. The designer&#39;s <em>&quot;alignment should be start&quot;</em> settles it as top-aligned, which is the default <code>justify-content</code> on that column.</p><p>Verified after the change: rows measure [190,190,190,190] / [168×4] / [155×4] / [155], the footer is 17px from the bottom on every card (16px padding + the 1px border, since <code>getBoundingClientRect</code> is the border box), and the slack lands after the legend (35px and 13px on the stretched cards, 0 where there was nothing to absorb). At a 788px page the grid drops to two columns and rows stay equal. The component&#39;s own demo is unaffected — all its cards carry identical content, so stretching is a no-op there.</p>',66)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
